d<-file.path(OUT,'07_sensitivity_analysis');m<-fread(file.path(OUT,'00_input_audit/C5_metadata.csv'));sm<-m[clinical_group!='Normal',.(LLPS_mean=mean(LLPS77_AUC),LLPS_median=median(LLPS77_AUC),C5_cells=.N),by=.(patient_id,dataset)];rr<-list();kk<-0L;ddall<-list()
for(th in c(10,20,30)){folder<-c('01_threshold10','02_threshold20','03_threshold30')[match(th,c(10,20,30))];n<-fread(file.path(PREV,folder,'network_all_specimens.csv'));n[,`:=`(LR_count=as.numeric(LR_count),weight=as.numeric(weight))];n<-n[clinical_group!='Normal'&eligible==TRUE&((sender=='Fibro_C5'&receiver!='Fibro_C5')|(receiver=='Fibro_C5'&sender!='Fibro_C5'))];n[,`:=`(direction=ifelse(sender=='Fibro_C5','outgoing','incoming'),partner=ifelse(sender=='Fibro_C5',receiver,sender))];tot<-n[,.(weight=sum(weight),LR_count=sum(LR_count)),by=.(specimen_id,patient_id,dataset,direction)];tot[,partner:='TOTAL'];n<-rbindlist(list(n[,.(specimen_id,patient_id,dataset,direction,partner,weight,LR_count)],tot),use.names=TRUE);p<-n[,.(weight=median(weight),LR_count=median(LR_count),specimens=.N),by=.(patient_id,dataset,direction,partner)];p<-merge(p,sm,by=c('patient_id','dataset'));p[,min_cells:=th];p[,within_dataset_state:=ifelse(LLPS_mean>median(LLPS_mean),'high','low'),by=.(dataset,direction,partner)];ddall[[as.character(th)]]<-p
for(scope in c('ALL',paste0('dataset:',unique(p$dataset)),paste0('exclude:',unique(p$dataset))))for(di in unique(p$direction))for(pa in unique(p$partner)){z<-p[direction==di&partner==pa];if(startsWith(scope,'dataset:'))z<-z[dataset==sub('dataset:','',scope)];if(startsWith(scope,'exclude:'))z<-z[dataset!=sub('exclude:','',scope)];N<-nrow(z);if(N<3)next
for(metric in c('weight','LR_count')){v<-z[[metric]];score<-z$LLPS_mean;valid<-sd(v)>0&&sd(score)>0;pear<-spear<-bp<-beta<-NA_real_;if(valid){pear<-cor(v,score);spear<-cor(v,score,method='spearman');X<-if(uniqueN(z$dataset)>1)model.matrix(~LLPS_mean+factor(dataset),z)else model.matrix(~LLPS_mean,z);if(N>=5&&qr(X)$rank==ncol(X)&&N-ncol(X)>=3){fit<-lm.fit(X,v);se<-sqrt(sum(fit$residuals^2)/(N-ncol(X))*diag(solve(crossprod(X))));beta<-fit$coefficients[2];bp<-2*pt(-abs(beta/se[2]),df=N-ncol(X))}};kk<-kk+1L;rr[[kk]]<-data.table(min_cells=th,stratum=scope,direction=di,partner=pa,metric=metric,n_patients=N,pearson=pear,spearman=spear,adjusted_beta=beta,adjusted_p=bp,high_patient_median=if(any(z$within_dataset_state=='high'))median(v[z$within_dataset_state=='high'])else NA_real_,low_patient_median=median(v[z$within_dataset_state=='low']))}}
};r<-rbindlist(rr);r[,FDR:=p.adjust(adjusted_p,'BH'),by=.(min_cells,stratum,metric)];writecsv(r,file.path(d,'unsplit_C5_continuous_communication.csv'));writecsv(rbindlist(ddall),file.path(d,'unsplit_C5_patient_plot_data.csv'));cat('CONTINUOUS UNSPLIT COMPLETE\n')
